//! Differential truth for the page-scraping sublayer of `media_resolve.py`,
//! copied out of the Python oracle's own answers: `/tmp/mr8_oracle.py` wrote
//! `/tmp/mr8_truth.txt`, and every expectation below is `json.dumps` of one of
//! its rows, re-rendered as a Rust literal. Nothing here was typed from memory,
//! nothing here reads `/tmp`, and nothing here asks the network -- the `scrape`
//! rows all hand the function a body, which is the seam the oracle itself used.
//!
//! Three rows exist in the truth file and cannot exist here, each for a different
//! reason, and the reason is the interesting part:
//!
//! * `parser` carries an `exc` column that is `null` in all 101 rows. The
//!   reference wrapped `feed`/`close` in a `try` because a malformed page *could*
//!   raise; over this corpus it never did, so there is no failure to reproduce and
//!   no Rust type for one. The rows below therefore assert the answer, not the
//!   absence of a panic -- `HtmlParser` has no error channel to panic through.
//! * `lit` index 7 feeds `None`. [`crate::resolve::literal_urls`] takes `&str`, so
//!   that call has no spelling in this crate; index 6 feeds `""` and answers the
//!   same empty list, which is the fact the row was there to establish.
//! * `dec` index 999 calls `decode_body("already str", ...)`, which is CPython's
//!   `isinstance(raw, str)` passthrough. This port's seam is `&[u8]`
//!   ([`crate::resolve::decode_body`]), so the branch does not exist to be fed.
//!
//! The `parser` rows do what the oracle does -- `feed` then `close`. The
//! `scrape` rows do what the product does, which is **feed and never close**
//! (see the docstring on [`crate::resolve::scrape_page`]). The reason for that
//! was measured rather than assumed, because the obvious story is false:
//! CPython's `check_for_whole_start_tag` refuses a partial start tag **even at
//! `close()`**, so a page cut inside `<video src="…` leaves the attribute
//! unsampled either way -- `sp_13` and `sp_14` answer identically with or
//! without the call, and they are in the corpus to say so. What `close()` does
//! flush is buffered character data, and `<title>` is the only data
//! `scrape_page` reads: `sp_10`, `sp_11`, `sp_12`, `sp_15`, `sp_16`, `sp_17`
//! each gain a title the reference never had if the seam closes. Inserting
//! `parser.close()` there turns those six red and nothing else.


#[allow(dead_code)]
fn esc(s: &str) -> String {
    let mut out = String::from("\"");
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

#[allow(dead_code)]
fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("valid hex"))
        .collect()
}
#[allow(dead_code)]
fn pairs_json(pairs: &[(String, String)]) -> String {
    if pairs.is_empty() {
        return "[]".to_string();
    }
    let mut out = String::from("[");
    for (i, (a, b)) in pairs.iter().enumerate() {
        if i > 0 {
            out.push_str(", ");
        }
        out.push_str(&format!("[{}, {}]", esc(a), esc(b)));
    }
    out.push(']');
    out
}
#[allow(dead_code)]
fn cands_json(cands: &[crate::resolve::Candidate]) -> String {
    if cands.is_empty() {
        return "[]".to_string();
    }
    let mut out = String::from("[");
    for (i, c) in cands.iter().enumerate() {
        if i > 0 {
            out.push_str(", ");
        }
        // `title` is Rust `None` where the page had no title and Python keeps the
        // empty string; `""` is what the oracle's rows carry for that case, so the
        // two are compared there. Same collapse `rend_row5` already makes.
        out.push_str(&format!(
            "{{\"url\": {}, \"origin\": {}, \"label\": {}, \"title\": {}}}",
            esc(&c.url),
            esc(&c.engine),
            esc(&c.label),
            esc(c.title.as_deref().unwrap_or(""))
        ));
    }
    out.push(']');
    out
}

