#[test]
fn the_page_parser_reports_every_attribute_row_and_the_title_it_kept() {
    crate::pin_test_dir();
    assert_eq!(
        PARSER_CASES.len(),
        BODIES.len(),
        "parser rows pair by index with BODIES"
    );
    assert_eq!(BODIES.len(), 101, "the body corpus moved");
    for (i, (id, want_found, want_title)) in PARSER_CASES.iter().enumerate() {
        let mut parser = crate::html::HtmlParser::new(crate::resolve::PageParser::new());
        parser.feed(BODIES[i]);
        parser.close();
        let sink = &parser.sink;
        assert_eq!(pairs_json(&sink.found), *want_found, "{}", id);
        assert_eq!(esc(&sink.page_title), *want_title, "{} title", id);
    }
}

#[test]
fn the_meta_regex_reads_only_the_video_open_graph_names() {
    crate::pin_test_dir();
    assert_eq!(OG_CASES.len(), BODIES.len(), "og rows pair by index with BODIES");
    for (i, (id, want)) in OG_CASES.iter().enumerate() {
        assert_eq!(pairs_json(&crate::resolve::meta_og_video(BODIES[i])), *want, "{}", id);
    }
}

#[test]
fn literal_suffixes_are_unescaped_before_they_are_scanned() {
    crate::pin_test_dir();
    assert_eq!(LIT_CASES.len(), 19, "19 of 20 lit rows are spellable here (see header)");
    for (id, body, want) in LIT_CASES {
        assert_eq!(pairs_json(&crate::resolve::literal_urls(body)), *want, "{}", id);
    }
}

#[test]
fn scraping_a_page_states_only_what_the_html_states_outright() {
    crate::pin_test_dir();
    assert_eq!(SCRAPE_CASES.len(), 18, "the scrape corpus moved");
    for (id, page_url, body, want) in SCRAPE_CASES {
        let found = crate::resolve::scrape_page(*page_url, Some(body), None)
            .unwrap_or_else(|err| panic!("{}: scrape_page raised {:?}", id, err));
        assert_eq!(cands_json(&found), *want, "{}", id);
    }
}

#[test]
fn decoding_a_body_walks_the_charset_chain_and_lands_on_replace() {
    crate::pin_test_dir();
    assert_eq!(DECODE_CASES.len(), 22, "22 of 23 dec rows are spellable here (see header)");
    for (id, raw_hex, cs, want) in DECODE_CASES {
        let got = crate::resolve::decode_body(&unhex(raw_hex), *cs);
        assert_eq!(esc(&got), *want, "{}", id);
    }
}

#[test]
fn utf8_replace_answers_for_every_byte_and_every_truncation() {
    crate::pin_test_dir();
    assert_eq!(REPLACE_CASES.len(), 476, "the rep corpus moved");
    for (id, raw_hex, want) in REPLACE_CASES {
        let got = crate::resolve::utf8_replace(&unhex(raw_hex));
        assert_eq!(esc(&got), *want, "{}", id);
    }
}
